style.css:
@-moz-document domain("shibidp.unipr.it") {
/* Palette */
:root {
  --bg-main: #131419;
  --bg-gradient: linear-gradient(135deg, #131419 0%, #181922 100%);
  --glass-bg: rgba(22, 23, 32, 0.96);
  --glass-bg-light: rgba(22, 23, 32, 0.99);
  --accent: #5a5f7a;
  --accent-2: #23243a;
  --accent-hover-bg: #23243a;
  --accent-hover-text: #aeb3d1;
  --text-main: #e6e7ef;
  --text-secondary: #a1a3b8;
  --text-muted: #6b6e7f;
  --shadow: 0 8px 32px 0 rgba(20, 22, 40, 0.14);
}

/* Sfondo generale e wrapper */
html, body, .wrapper {
  background: var(--bg-gradient) !important;
  min-height: 100vh;
  color: var(--text-main) !important;
  margin: 0 !important;
  padding: 0 !important;
}
.wrapper {
  border-radius: 24px;
  box-shadow: var(--shadow);
  padding: 2rem 0 0 0 !important;
}

/* Header e logo */
.uniprHeader, .uniprTesta {
  background: #181922 !important;
  border-radius: 24px 24px 0 0 !important;
  margin: 0 !important;
  padding: 0.5em 1em !important;
  box-shadow: 0 4px 24px 0 rgba(35,36,58,0.10) !important;
  display: flex;
  align-items: center;
  min-height: 90px;
  justify-content: center;
}
.uniprLogo, #logo, img#logo {
  background: none !important;
  border-radius: 16px !important;
  box-shadow: none !important;
  margin: 0 !important;
  padding: 0 !important;
  height: 80px;
  width: auto;
  display: block;
  filter: brightness(70%);
}

/* Footer */
footer, .container-footer {
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
  border-radius: 18px !important;
  padding: 0.5em 0 !important;
  color: var(--text-muted) !important;
  text-align: center;
}
.container-footer {
  background: rgba(22, 23, 32, 0.92) !important;
  box-shadow: 0 2px 12px 0 rgba(35,36,58,0.08) !important;
  padding: 1.2em 1.5em !important;
}
.footer-text {
  color: var(--text-muted) !important;
  text-align: center;
}

/* Contenitore principale */
.container {
  max-width: 1200px;
  margin: 0 auto !important;
  padding: 0 1.2rem !important;
  background: none !important;
  box-shadow: none !important;
  border: none !important;
}

/* Layout colonne */
.content {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: flex-start;
  gap: 1.2rem;
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
}
@media (max-width: 1100px) {
  .content {
    flex-direction: column;
    align-items: center;
    gap: 0.8rem;
  }
}
@media (max-width: 900px) {
  .content {
    flex-direction: column;
    align-items: center;
    gap: 1rem;
  }
  .column_registrati, .column.one, .column.two {
    max-width: 98vw;
    min-width: 0;
    width: 100%;
    margin: 0.7rem 0 !important;
  }
}
@media (max-width: 600px) {
  .column_registrati, .column.one, .column.two {
    padding: 0.7rem 0.3rem !important;
  }
  .container {
    padding: 0 0.2rem !important;
  }
}

/* Colonne principali */
.column_registrati, .column.one, .column.two {
  max-width: 340px;
  min-width: 260px;
  width: 100%;
  margin: 1.2rem 0.5rem !important;
  padding: 1.2rem 1rem !important;
  border-radius: 18px !important;
  box-shadow: 0 4px 18px 0 rgba(35,36,58,0.10) !important;
  background: var(--glass-bg) !important;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow: hidden;
  color: var(--text-main) !important;
}
.tab-content,
.cornice_login_ateneo,
.uniprIdem {
  width: 100%;
  max-width: 100%;
  box-sizing: border-box;
  overflow-wrap: break-word;
  word-break: break-word;
  overflow: hidden;
}
.tab-content {
  padding: 1rem 1.2rem;
  color: var(--text-main) !important;
  background: var(--glass-bg-light) !important;
  border-radius: 18px !important;
  box-shadow: 0 4px 18px 0 rgba(35,36,58,0.10) !important;
}

/* Titoli colonne */
.titoli_colonne, .titoli_colonna_registrati {
  color: var(--accent) !important;
  font-size: 0.9rem !important;
  font-weight: 800 !important;
  text-align: center !important;
  background: none !important;
  box-shadow: none !important;
  border: none !important;
  border-radius: 0 !important;
  margin-bottom: 0.7em !important;
  padding: 0.2em 0 !important;
  letter-spacing: 0.01em !important;
  cursor: default !important;
  transition: none !important;
  text-shadow: 0 2px 8px #000a, 0 1px 0 #2228;
}
.titoli_colonne:hover, .titoli_colonna_registrati:hover {
  background: none !important;
}
.titoli_colonne span,
.titoli_colonna_registrati span, .titoli_colonna_registrati div {
  color: var(--accent-hover-text) !important;
  background: #23243a33 !important;
  font-weight: inherit !important;
  text-shadow: 0 2px 8px #000a, 0 1px 0 #2228;
  border-radius: 10px
}

/* Centra tutto nella colonna di login */
.column.one, .column.one > *, #tabAccedi, .cornice_login_ateneo, .form-element-wrapper, .sp_info, #pulsanteEntraUnipr, .italia-it-button, img, .footer-text {
  margin-left: auto !important;
  margin-right: auto !important;
  text-align: center !important;
}
.column.one {
  display: flex !important;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
}

/* Bottoni principali */
.italia-it-button, .button-spid {
  background: var(--accent-2) !important;
  color: #e6e7ef !important;
  border: 1.5px solid var(--accent) !important;
  border-radius: 10px !important;
  padding: 0.5em 1em !important;
  font-size: 1em !important;
  font-weight: 600 !important;
  box-shadow: 0 2px 8px 0 rgba(35,36,58,0.10) !important;
  transition: background 0.2s, color 0.2s, transform 0.1s, box-shadow 0.2s !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 0.7em !important;
  margin-bottom: 0.5em !important;
  width: 90% !important;
  max-width: 320px;
  min-height: 38px !important;
  text-align: center !important;
  text-decoration: none !important;
}
.italia-it-button:hover, .button-spid:hover {
  background: #444556 !important;
  color: #25274a !important;
  transform: scale(1.04) !important;
  box-shadow: 0 6px 32px 0 rgba(35,36,58,0.18) !important;
}
.italia-it-button-icon img, .button-icon-spid-cie-unipr img, .button-icon-unipr img {
  width: 28px !important;
  height: 28px !important;
  padding: 0.1em !important;
}
.italia-it-button-text, .italia-it-button-text-unipr {
  color: var(--accent-hover-text) !important;
  font-weight: 500 !important;
  font-size: 1em !important;
}

/* Pulsante UNIPR */
#pulsanteEntraUnipr {
  max-width: 400px;
  width: 100%;
  margin: 0 auto 1em auto !important;
  display: block;
  box-sizing: border-box;
}

/* Responsive bottoni */
@media (max-width: 900px) {
  .form-element-wrapper {
    display: flex;
    flex-direction: column;
    align-items: stretch;
  }
  #pulsanteEntraUnipr {
    width: 100% !important;
    margin: 0 auto !important;
    display: block !important;
  }
}

/* Form e input */
.form-element-wrapper {
  margin-bottom: 0.7em !important;
  padding: 0 !important;
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box;
}
input.form-element, input.form-field {
  font-size: 1em !important;
  padding: 0.4em 0.7em !important;
  min-height: 36px !important;
  border-radius: 8px !important;
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box;
  background: #181922 !important;
  color: var(--text-main) !important;
  border: 1.5px solid var(--accent-2) !important;
  filter: none;
}

/* Tooltip solo su click/focus */
.tooltip-box, .tooltip-box-2 {
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s;
  background: #23243a;
  color: var(--accent-hover-text);
  border-radius: 8px;
  padding: 0.5em 1em;
  border: 1px solid var(--accent-2);
}
.tooltip-wrapper:focus-within .tooltip-box,
.tooltip-wrapper:focus-within .tooltip-box-2,
.tooltip-wrapper.active .tooltip-box,
.tooltip-wrapper.active .tooltip-box-2 {
  pointer-events: auto;
  opacity: 1;
}

/* Box aiuto/IDEM */
.uniprIdem {
  background: rgba(90, 95, 122, 0.10) !important;
  border-radius: 14px !important;
  padding: 1em 1.2em !important;
  margin-top: 1.5em !important;
  text-align: center !important;
  box-shadow: none !important;
  color: var(--text-secondary) !important;
}

/* Lista aiuto */
.list-help {
  background: transparent !important;
  border-radius: 12px !important;
  padding-left: 1.2em !important;
  margin: 0 !important;
}
.list-help-item {
  margin-bottom: 0.7em !important;
  font-size: 1em !important;
  color: var(--text-secondary) !important;
}
.item-marker {
  color: var(--accent) !important;
  font-weight: bold !important;
  margin-right: 0.5em !important;
}

/* Immagini */
img {
  border-radius: 10px !important;
  max-width: 100% !important;
  height: auto !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 10px;
  background: rgba(22,23,32,0.2);
}
::-webkit-scrollbar-thumb {
  background: var(--accent-2);
  border-radius: 8px;
}

/* Link */
a, .italia-it-button-text-unipr {
  color: var(--accent-hover-text) !important;
}
a:hover {
  color: var(--accent) !important;
  background: var(--accent-hover-bg) !important;
}

.cornice_login_ateneo {
  border: 2px solid var(--accent-2);
  border-radius: 10px;
  background-color: transparent;
  width: 352px;
  margin-bottom: 60px;
  padding: 10px
}

input {
  filter: brightness(50%) !important;
  color: var(--text-main) !important;
  border: 1.5px solid var(--accent-2) !important;
  }
}
